          "code": "UPDATE tasks\nSET title = $1, version = version + 1\nWHERE id = $2\n  AND owner_id = $3\n  AND tenant_id = $4\n  AND version = $5\nRETURNING id, version;\n-- $3 и $4 берутся из проверенного контекста, не из тела клиента."
